CREATE TABLE cloud_pipeline_plans(quote_id text PRIMARY KEY REFERENCES cloud_quotes(id),kind text NOT NULL CHECK(kind IN ('storyboard','assembly')),stage text NOT NULL DEFAULT 'queued',story_model text NOT NULL DEFAULT '',clip_count integer NOT NULL DEFAULT 0,clip_duration integer NOT NULL DEFAULT 0,story jsonb NOT NULL DEFAULT '{"script":"","scenes":[]}',source_keys jsonb NOT NULL DEFAULT '[]',output_key text NOT NULL DEFAULT '',updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE cloud_pipeline_clips(quote_id text NOT NULL REFERENCES cloud_pipeline_plans(quote_id),position integer NOT NULL,prompt text NOT NULL,title text NOT NULL,status text NOT NULL DEFAULT 'queued',provider_id text NOT NULL DEFAULT '',output_key text NOT NULL DEFAULT '',PRIMARY KEY(quote_id,position));
CREATE INDEX ON cloud_pipeline_clips(quote_id,status);
